  Definition POSTLOOP (fd : Z) (r : rd_result) (s : APS) (RNG : footprint) (ms : machine_state) : Prop :=
    match r with
    | RdExit => aat_exit 2 s RNG ms
    | RdDone b c => RDBRK' fd b c s RNG ms
    end.

